import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"Referencia de comandos CLI","description":"","frontmatter":{"title":"Referencia de comandos CLI","docId":"developer.cli","translationKey":"developer.cli","locale":"es","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"6bb485d6e8067cb1639fb20821c45b79941245692f0b6c7525f2b3bee930048b","translationRevision":"4bed4172e24c685db852a6786742e40d68364c85f0ce82373b5d5eb93d58d0e0","order":75},"headers":[],"relativePath":"es/developer/cli.md","filePath":"es/developer/cli.md","lastUpdated":1795731074000}`),a={name:`es/developer/cli.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="cli-command-reference" tabindex="-1">Referencia de comandos CLI <a class="header-anchor" href="#cli-command-reference" aria-label="Permalink to “Referencia de comandos CLI”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo y requisitos”">​</a></h2><p>Descubre cada forma de comando <code>tiktools</code> sin leer el código Rust ni analizar la salida de ayuda humana. Necesitas un binario <code>tiktools</code> compilado correspondiente; la referencia es offline y nunca requiere un host activo. La fuente canónica es el registro de especificaciones en <code>crates/tiktools-cli/src/commands/spec.rs</code>; cada módulo de dominio posee las cadenas de uso que su parser reporta en errores, por lo que esta referencia no puede divergir de lo que el parser acepta.</p><h2 id="inspect-help-offline" tabindex="-1">Inspeccionar la ayuda offline <a class="header-anchor" href="#inspect-help-offline" aria-label="Permalink to “Inspeccionar la ayuda offline”">​</a></h2><p>La ayuda humana agrupa los verbos por dominio; el filtro muestra una sección de dominio. La forma <code>--json</code> imprime el registro legible por máquina que todo agente debería preferir: uso, resumen y marcador destructivo por verbo, más las convenciones globales de la CLI, versionado por el campo <code>schema</code> superior.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>Los errores de uso imprimen solo la forma relevante con una pista en lugar de la página completa, así que un error tipográfico nunca desplaza la terminal. El código de salida 2 siempre significa error de uso; consulta el pie de convenciones para las reglas de resolución del host, salida y redacción de secretos.</p><h2 id="generated-command-reference" tabindex="-1">Referencia de comandos generada <a class="header-anchor" href="#generated-command-reference" aria-label="Permalink to “Referencia de comandos generada”">​</a></h2><p>Generada desde la instantánea de ayuda CLI versionada en <code>docs/contracts/cli-help.json</code>; el binario sigue siendo la autoridad. Las líneas de uso son sintaxis del parser y permanecen en inglés en todas las locales; los resúmenes y convenciones provienen de los catálogos de traducción de la propia CLI, por lo que esta referencia no puede divergir de lo que <code>tiktools help</code> imprime en el mismo idioma. Los verbos marcados como destructivos mutan o destruyen estado; los scripts deberían confirmar antes de ejecutarlos.</p><p><code>tiktools [--json] [--standalone] &lt;command&gt; [args]</code></p><h3 id="tiktools-plugin-—-instalar-y-gestionar-plugins" tabindex="-1"><code>tiktools plugin</code> — instalar y gestionar plugins <a class="header-anchor" href="#tiktools-plugin-—-instalar-y-gestionar-plugins" aria-label="Permalink to “tiktools plugin — instalar y gestionar plugins”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>listar los plugins instalados</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>leer un plugin</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>instalar desde un archivo, id@version o url</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>desinstalar un plugin <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>buscar paquetes en el registro</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>inspeccionar una especificación de paquete antes de instalar</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>listar los plugins instalados con actualizaciones disponibles</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>actualizar un plugin</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>actualizar todos los plugins desactualizados</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>volver a una versión anterior <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>listar las versiones disponibles de un plugin</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>fijar un plugin a su versión actual</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>quitar la fijación de versión</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>establecer el canal y la política de autoactualización</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>listar los trabajos de paquetes</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>inspeccionar un trabajo de paquete</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>cancelar un trabajo de paquete en curso <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>activar un plugin</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>desactivar un plugin</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>iniciar un plugin</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>detener un plugin <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>leer la configuración de un plugin</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>escribir la configuración de un plugin</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>restablecer la configuración de un plugin <strong>destructivo</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>comprobación de salud de un plugin</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>opciones de un tipo de acción o campo</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>ejecutar una acción de plugin</td></tr><tr><td><code>tiktools plugin commands</code></td><td>listar los comandos aportados por los plugins instalados</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>describir un comando aportado</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>invocar un comando aportado por un plugin</td></tr></tbody></table><h3 id="tiktools-cloud-—-cuenta-cloud-y-copia-restauracion-portatil-anula-con-tiktools-cloud-origin" tabindex="-1"><code>tiktools cloud</code> — cuenta cloud y copia/restauración portátil (anula con TIKTOOLS_CLOUD_ORIGIN) <a class="header-anchor" href="#tiktools-cloud-—-cuenta-cloud-y-copia-restauracion-portatil-anula-con-tiktools-cloud-origin" aria-label="Permalink to “tiktools cloud — cuenta cloud y copia/restauración portátil (anula con TIKTOOLS_CLOUD_ORIGIN)”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools cloud status</code></td><td>estado de la cuenta cloud</td></tr><tr><td><code>tiktools cloud login</code></td><td>iniciar sesión mediante el navegador del sistema</td></tr><tr><td><code>tiktools cloud logout</code></td><td>cerrar sesión <strong>destructivo</strong></td></tr><tr><td><code>tiktools cloud restore</code></td><td>restaurar la sesión cloud</td></tr><tr><td><code>tiktools cloud backup create [--out FILE]</code></td><td>escribir un archivo de copia portátil</td></tr><tr><td><code>tiktools cloud backup preview &lt;file&gt;</code></td><td>inspeccionar un archivo de copia</td></tr><tr><td><code>tiktools cloud backup restore &lt;file&gt; [--yes]</code></td><td>restaurar un archivo de copia <strong>destructivo</strong></td></tr></tbody></table><h3 id="tiktools-publisher-—-flujo-de-publicador-cloud-requiere-iniciar-sesion" tabindex="-1"><code>tiktools publisher</code> — flujo de publicador cloud (requiere iniciar sesión) <a class="header-anchor" href="#tiktools-publisher-—-flujo-de-publicador-cloud-requiere-iniciar-sesion" aria-label="Permalink to “tiktools publisher — flujo de publicador cloud (requiere iniciar sesión)”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools publisher list</code></td><td>listar los espacios de publicador</td></tr><tr><td><code>tiktools publisher create &lt;namespace&gt;</code></td><td>crear un espacio de publicador</td></tr><tr><td><code>tiktools publisher delete &lt;namespace-or-publisher-id&gt;</code></td><td>eliminar un espacio o publicador <strong>destructivo</strong></td></tr><tr><td><code>tiktools publisher keys &lt;publisher-id&gt;</code></td><td>listar las claves de firma de un publicador</td></tr><tr><td><code>tiktools publisher enroll &lt;publisher-id&gt; [--key-id &lt;id&gt;]</code></td><td>inscribir una clave de publicador; lee la contraseña del backend desde stdin</td></tr><tr><td><code>tiktools publisher upload &lt;publisher-id&gt; &lt;path&gt;</code></td><td>subir un paquete de plugin</td></tr><tr><td><code>tiktools publisher submit &lt;upload-id&gt; &lt;publisher-key-id&gt; &lt;plugin-id&gt; &lt;version&gt; [--target any]</code></td><td>enviar una subida a revisión</td></tr><tr><td><code>tiktools publisher release &lt;release-id&gt;</code></td><td>crear una release</td></tr><tr><td><code>tiktools publisher publish &lt;release-id&gt;</code></td><td>publicar una release</td></tr></tbody></table><h3 id="tiktools-registry-—-registros-de-paquetes-y-el-catalogo-cloud" tabindex="-1"><code>tiktools registry</code> — registros de paquetes y el catálogo cloud <a class="header-anchor" href="#tiktools-registry-—-registros-de-paquetes-y-el-catalogo-cloud" aria-label="Permalink to “tiktools registry — registros de paquetes y el catálogo cloud”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>listar los registros configurados</td></tr><tr><td><code>tiktools registry refresh</code></td><td>actualizar los metadatos del registro</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>mostrar un paquete del registro</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>buscar en el catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>página de resúmenes del catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versiones de un paquete del catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>capacidades de paginación del catálogo cloud</td></tr><tr><td><code>tiktools registry defaults</code></td><td>configuración por defecto del registro</td></tr></tbody></table><h3 id="tiktools-processor-—-procesadores-de-eventos" tabindex="-1"><code>tiktools processor</code> — procesadores de eventos <a class="header-anchor" href="#tiktools-processor-—-procesadores-de-eventos" aria-label="Permalink to “tiktools processor — procesadores de eventos”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>listar los procesadores</td></tr><tr><td><code>tiktools processor status</code></td><td>estado de la canalización de procesadores</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>ejecutar un procesador contra un evento de muestra</td></tr></tbody></table><h3 id="tiktools-live-—-conexion-con-tiktok-live" tabindex="-1"><code>tiktools live</code> — conexión con TikTok LIVE <a class="header-anchor" href="#tiktools-live-—-conexion-con-tiktok-live" aria-label="Permalink to “tiktools live — conexión con TikTok LIVE”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>conectar a una sala en vivo</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>elegir una sala en vivo interactivamente</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>descubrir canales en vivo; funciona sin sesión</td></tr><tr><td><code>tiktools live disconnect</code></td><td>desconectar de la sala actual <strong>destructivo</strong></td></tr><tr><td><code>tiktools live status</code></td><td>estado actual de la conexión</td></tr></tbody></table><h3 id="tiktools-points-—-puntos-de-fidelidad-de-espectadores" tabindex="-1"><code>tiktools points</code> — puntos de fidelidad de espectadores <a class="header-anchor" href="#tiktools-points-—-puntos-de-fidelidad-de-espectadores" aria-label="Permalink to “tiktools points — puntos de fidelidad de espectadores”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools points config get</code></td><td>leer la configuración de puntos</td></tr><tr><td><code>tiktools points config set k=v...</code></td><td>actualizar la configuración de puntos</td></tr><tr><td><code>tiktools points viewer get &lt;id&gt;</code></td><td>leer el saldo de un espectador</td></tr><tr><td><code>tiktools points adjust &lt;id&gt; &lt;delta&gt;</code></td><td>sumar o restar puntos a un espectador</td></tr><tr><td><code>tiktools points leaderboard [--limit N]</code></td><td>espectadores con mayor saldo</td></tr><tr><td><code>tiktools points reset [id]</code></td><td>restablecer el saldo de un espectador o de todos <strong>destructivo</strong></td></tr></tbody></table><h3 id="tiktools-ranking-—-definiciones-y-estado-de-rankings-de-espectadores" tabindex="-1"><code>tiktools ranking</code> — definiciones y estado de rankings de espectadores <a class="header-anchor" href="#tiktools-ranking-—-definiciones-y-estado-de-rankings-de-espectadores" aria-label="Permalink to “tiktools ranking — definiciones y estado de rankings de espectadores”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools ranking list</code></td><td>listar las definiciones de ranking</td></tr><tr><td><code>tiktools ranking metrics</code></td><td>métricas disponibles para las definiciones de ranking</td></tr><tr><td><code>tiktools ranking create --record &lt;json&amp;#124;@file&gt;</code></td><td>crear una definición de ranking</td></tr><tr><td><code>tiktools ranking update --record &lt;json&amp;#124;@file&gt;</code></td><td>actualizar una definición de ranking</td></tr><tr><td><code>tiktools ranking get &lt;id&gt;</code></td><td>leer un ranking</td></tr><tr><td><code>tiktools ranking snapshot &lt;id&gt;</code></td><td>clasificación actual de un ranking</td></tr><tr><td><code>tiktools ranking delete &lt;id&gt;</code></td><td>eliminar un ranking <strong>destructivo</strong></td></tr><tr><td><code>tiktools ranking reset &lt;id&gt;</code></td><td>restablecer el estado acumulado <strong>destructivo</strong></td></tr><tr><td><code>tiktools ranking pause &lt;id&gt;</code></td><td>pausar la acumulación</td></tr><tr><td><code>tiktools ranking resume &lt;id&gt;</code></td><td>reanudar la acumulación</td></tr><tr><td><code>tiktools ranking contribute --record &lt;json&amp;#124;@file&gt;</code></td><td>añadir una contribución externa</td></tr></tbody></table><h3 id="tiktools-competition-—-competiciones-cronometradas-de-espectadores" tabindex="-1"><code>tiktools competition</code> — competiciones cronometradas de espectadores <a class="header-anchor" href="#tiktools-competition-—-competiciones-cronometradas-de-espectadores" aria-label="Permalink to “tiktools competition — competiciones cronometradas de espectadores”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools competition list</code></td><td>listar las competiciones</td></tr><tr><td><code>tiktools competition get &lt;id&gt;</code></td><td>leer una competición</td></tr><tr><td><code>tiktools competition create --record &lt;json&amp;#124;@file&gt;</code></td><td>crear una competición</td></tr><tr><td><code>tiktools competition update --record &lt;json&amp;#124;@file&gt;</code></td><td>actualizar una competición</td></tr><tr><td><code>tiktools competition delete &lt;id&gt;</code></td><td>eliminar una competición <strong>destructivo</strong></td></tr><tr><td><code>tiktools competition state &lt;id&gt;</code></td><td>estado actual de la competición</td></tr><tr><td><code>tiktools competition results &lt;id&gt;</code></td><td>resultados finales o intermedios</td></tr><tr><td><code>tiktools competition action --record &lt;json&amp;#124;@file&gt;</code></td><td>registrar una acción de competición</td></tr><tr><td><code>tiktools competition mark-action-uncertain --record &lt;json&amp;#124;@file&gt;</code></td><td>marcar una acción como incierta</td></tr><tr><td><code>tiktools competition resolve-action --record &lt;json&amp;#124;@file&gt;</code></td><td>resolver una acción incierta</td></tr><tr><td><code>tiktools competition start &lt;id&gt;</code></td><td>iniciar una competición</td></tr><tr><td><code>tiktools competition finish &lt;id&gt;</code></td><td>finalizar una competición <strong>destructivo</strong></td></tr><tr><td><code>tiktools competition candidates &lt;id&gt;</code></td><td>candidatos a ganador</td></tr><tr><td><code>tiktools competition select-winner --record &lt;json&amp;#124;@file&gt;</code></td><td>seleccionar el ganador</td></tr><tr><td><code>tiktools competition pause &lt;id&gt;</code></td><td>pausar una competición</td></tr><tr><td><code>tiktools competition resume &lt;id&gt;</code></td><td>reanudar una competición</td></tr><tr><td><code>tiktools competition cancel &lt;id&gt;</code></td><td>cancelar una competición <strong>destructivo</strong></td></tr></tbody></table><h3 id="tiktools-automation-—-reglas-de-automatizacion-de-eventos-y-acciones" tabindex="-1"><code>tiktools automation</code> — reglas de automatización de eventos y acciones <a class="header-anchor" href="#tiktools-automation-—-reglas-de-automatizacion-de-eventos-y-acciones" aria-label="Permalink to “tiktools automation — reglas de automatización de eventos y acciones”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools automation list [--kind event&amp;#124;action&amp;#124;all]</code></td><td>listar las reglas de automatización</td></tr><tr><td><code>tiktools automation context [--event-type t]</code></td><td>contexto de plantilla disponible para las reglas</td></tr><tr><td><code>tiktools automation get &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>leer una regla</td></tr><tr><td><code>tiktools automation create --record json [--kind event&amp;#124;action]</code></td><td>crear una regla</td></tr><tr><td><code>tiktools automation update &lt;id&gt; --record json [--kind event&amp;#124;action]</code></td><td>actualizar una regla</td></tr><tr><td><code>tiktools automation delete &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>eliminar una regla <strong>destructivo</strong></td></tr><tr><td><code>tiktools automation enable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>activar una regla</td></tr><tr><td><code>tiktools automation disable &lt;id&gt; [--kind event&amp;#124;action]</code></td><td>desactivar una regla</td></tr><tr><td><code>tiktools automation test (--id &lt;id&gt; &amp;#124; --record json) [--kind event&amp;#124;action] [--trigger t] [--event json]</code></td><td>probar una regla en seco contra un evento de muestra</td></tr><tr><td><code>tiktools automation fire --trigger &lt;type&gt; [--event json] [--record json]</code></td><td>disparar un trigger manualmente</td></tr><tr><td><code>tiktools automation moderation-penalty --points &lt;delta&gt;</code></td><td>aplicar una penalización de moderación en puntos</td></tr></tbody></table><h3 id="tiktools-globals-—-globales-clave-valor-compartidos-entre-plugins" tabindex="-1"><code>tiktools globals</code> — globales clave/valor compartidos entre plugins <a class="header-anchor" href="#tiktools-globals-—-globales-clave-valor-compartidos-entre-plugins" aria-label="Permalink to “tiktools globals — globales clave/valor compartidos entre plugins”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools globals list</code></td><td>listar todas las claves globales</td></tr><tr><td><code>tiktools globals get &lt;key&gt;</code></td><td>leer un global</td></tr><tr><td><code>tiktools globals set &lt;key&gt; &lt;value&gt;</code></td><td>escribir un global</td></tr><tr><td><code>tiktools globals delete &lt;key&gt;</code></td><td>eliminar un global <strong>destructivo</strong></td></tr></tbody></table><h3 id="tiktools-workflow-—-grafos-de-workflows-visuales" tabindex="-1"><code>tiktools workflow</code> — grafos de workflows visuales <a class="header-anchor" href="#tiktools-workflow-—-grafos-de-workflows-visuales" aria-label="Permalink to “tiktools workflow — grafos de workflows visuales”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools workflow list</code></td><td>listar los grafos de workflow guardados</td></tr><tr><td><code>tiktools workflow get &lt;id&gt;</code></td><td>leer un grafo</td></tr><tr><td><code>tiktools workflow save --record json</code></td><td>crear o reemplazar un grafo</td></tr><tr><td><code>tiktools workflow delete &lt;id&gt;</code></td><td>eliminar un grafo <strong>destructivo</strong></td></tr><tr><td><code>tiktools workflow enable &lt;id&gt;</code></td><td>activar un grafo</td></tr><tr><td><code>tiktools workflow disable &lt;id&gt;</code></td><td>desactivar un grafo</td></tr></tbody></table><h3 id="tiktools-media-—-validacion-y-reproduccion-de-archivos-multimedia" tabindex="-1"><code>tiktools media</code> — validación y reproducción de archivos multimedia <a class="header-anchor" href="#tiktools-media-—-validacion-y-reproduccion-de-archivos-multimedia" aria-label="Permalink to “tiktools media — validación y reproducción de archivos multimedia”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools media validate &lt;path&gt; [--kind audio&amp;#124;video&amp;#124;image&amp;#124;other]</code></td><td>validar un archivo multimedia antes de usarlo en acciones</td></tr></tbody></table><h3 id="tiktools-system-—-informacion-y-diagnostico-del-host" tabindex="-1"><code>tiktools system</code> — información y diagnóstico del host <a class="header-anchor" href="#tiktools-system-—-informacion-y-diagnostico-del-host" aria-label="Permalink to “tiktools system — información y diagnóstico del host”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools system info</code></td><td>versión del host e información del runtime</td></tr><tr><td><code>tiktools system health</code></td><td>informe de salud de los componentes</td></tr><tr><td><code>tiktools system snapshot</code></td><td>instantánea completa del estado para depuración</td></tr><tr><td><code>tiktools system doctor</code></td><td>diagnosticar problemas comunes de configuración</td></tr><tr><td><code>tiktools system request-input-access</code></td><td>pedir acceso de entrada al usuario del escritorio</td></tr><tr><td><code>tiktools system shutdown</code></td><td>apagar el host en ejecución <strong>destructivo</strong></td></tr></tbody></table><h3 id="tiktools-template-—-plantillas-de-automatizacion-y-perfiles-reutilizables" tabindex="-1"><code>tiktools template</code> — plantillas de automatización y perfiles reutilizables <a class="header-anchor" href="#tiktools-template-—-plantillas-de-automatizacion-y-perfiles-reutilizables" aria-label="Permalink to “tiktools template — plantillas de automatización y perfiles reutilizables”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools template import &lt;file&gt; [--param k=v]... [--event-name n] [--action-name n] [--dry-run] [--no-save] [--disabled]</code></td><td>importar una plantilla como reglas de automatización</td></tr><tr><td><code>tiktools template export --event &lt;id&gt; --out &lt;file&gt; [--title t] [--id template-id]</code></td><td>exportar una regla de eventos como plantilla</td></tr><tr><td><code>tiktools template list</code></td><td>listar las plantillas de la galería</td></tr><tr><td><code>tiktools template delete &lt;template-id&gt;</code></td><td>eliminar una plantilla <strong>destructivo</strong></td></tr><tr><td><code>tiktools template profile-import &lt;file&gt; [--param k=v]... [--dry-run] [--no-save] [--disabled]</code></td><td>importar un perfil de automatización completo</td></tr><tr><td><code>tiktools template profile-export --out &lt;file&gt; [--name n]</code></td><td>exportar el perfil de automatización</td></tr></tbody></table><h3 id="tiktools-api-—-superficie-de-control-generica-orientada-a-agentes-sobre-los-metodos-del-host" tabindex="-1"><code>tiktools api</code> — superficie de control genérica orientada a agentes sobre los métodos del host <a class="header-anchor" href="#tiktools-api-—-superficie-de-control-generica-orientada-a-agentes-sobre-los-metodos-del-host" aria-label="Permalink to “tiktools api — superficie de control genérica orientada a agentes sobre los métodos del host”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools api discover [--format json&amp;#124;human]</code></td><td>listar todos los métodos en vivo del registro del host</td></tr><tr><td><code>tiktools api schema &lt;method&gt; [--format json&amp;#124;human]</code></td><td>descripción, flags y esquemas de un método</td></tr><tr><td><code>tiktools api call &lt;method&gt; [params-json] [--timeout SEC] [--dry-run] [--confirm] [--redact&amp;#124;--secrets-visible] [--explain] [--format json&amp;#124;human] [--expected-revision N] [--command-id ID --host-instance-id ID] [--include-meta]</code></td><td>validar y ejecutar un método; los destructivos necesitan --confirm</td></tr><tr><td><code>tiktools api events [--topics t,...] [--timeout SEC] [--max-events N]</code></td><td>transmitir eventos de dominio NDJSON</td></tr><tr><td><code>tiktools api event get &lt;name&gt; [--type kind]... [--author text] [--limit N]</code></td><td>buscar en el diario acotado del feed</td></tr><tr><td><code>tiktools api verify [--coverage&amp;#124;--smoke] [--sandbox] [--timeout SEC]</code></td><td>verificar la superficie de control contra el host</td></tr></tbody></table><h3 id="tiktools-host-—-runtimes-de-host-sin-interfaz-y-el-paso-directo-de-rpc" tabindex="-1"><code>tiktools host</code> — runtimes de host sin interfaz y el paso directo de rpc <a class="header-anchor" href="#tiktools-host-—-runtimes-de-host-sin-interfaz-y-el-paso-directo-de-rpc" aria-label="Permalink to “tiktools host — runtimes de host sin interfaz y el paso directo de rpc”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools host --stdio [--events]</code></td><td>host sin interfaz en stdio; transmite eventos con --events</td></tr><tr><td><code>tiktools host --ipc</code></td><td>host sin interfaz en IPC local; rechaza si ya hay un host en ejecución</td></tr><tr><td><code>tiktools rpc &lt;method&gt; [params-json] &amp;#124; rpc --stdio [--events]</code></td><td>paso directo sin tipos a cualquier método del host</td></tr><tr><td><code>tiktools rpc --stdio [--events]</code></td><td>bucle de petición/respuesta NDJSON en stdio</td></tr></tbody></table><h3 id="tiktools-web-—-adaptador-de-navegador-local-requiere-la-feature-local-web" tabindex="-1"><code>tiktools web</code> — adaptador de navegador local (requiere la feature local-web) <a class="header-anchor" href="#tiktools-web-—-adaptador-de-navegador-local-requiere-la-feature-local-web" aria-label="Permalink to “tiktools web — adaptador de navegador local (requiere la feature local-web)”">​</a></h3><table tabindex="0"><thead><tr><th>Comando</th><th>Resumen</th></tr></thead><tbody><tr><td><code>tiktools web --assets &lt;directory&gt; [--port N] [--join-origin URL] [--multi-session]</code></td><td>servir el adaptador de navegador local; host --ipc debe estar en ejecución</td></tr><tr><td><code>tiktools web --print-code [--port N]</code></td><td>imprimir el código de emparejamiento activo sin reiniciar</td></tr><tr><td><code>tiktools web --reset-session [--port N]</code></td><td>revocar todos los navegadores emparejados e imprimir un código nuevo <strong>destructivo</strong></td></tr></tbody></table><h3 id="convenciones" tabindex="-1">Convenciones <a class="header-anchor" href="#convenciones" aria-label="Permalink to “Convenciones”">​</a></h3><ul><li><strong>resolución del host</strong>: los comandos se ejecutan contra el host en ejecución por IPC local; cuando no hay un host activo fallan con host_unavailable en lugar de iniciar un segundo runtime. Usa <code>tiktools --json system info</code> como sonda ligera: salida 0 significa que un host respondió, salida 3 que el host IPC no está disponible. --standalone ejecuta el comando contra un runtime aislado en proceso.</li><li><strong>salida</strong>: stdout lleva el resultado; los diagnósticos van a stderr. --json imprime el objeto de resultado crudo; sin él, las listas imprimen una línea por elemento. Los valores json pueden usar @path para leer desde un archivo. La ayuda humana sigue el locale de visualización: TIKTOOLS_LANG anula la cadena LC_ALL/LC_MESSAGES/LANG, y la salida de máquina se mantiene independiente del locale.</li><li><strong>códigos de salida</strong>: 0 correcto, 1 error de operación, 2 error de uso, 3 fallo de transporte.</li><li><strong>secretos</strong>: live connect/pick leen la cookie de sesión de --session-cookie o de la variable de entorno TIKTOOLS_SESSION_COOKIE (el flag gana); el valor nunca aparece en los diagnósticos. api call oculta los secretos de su salida salvo que se pase --secrets-visible, y rechaza los métodos destructivos sin --confirm.</li></ul><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to “Detalles de operación”">​</a></h2><p>La instantánea se regenera desde un binario compilado con <code>--features local-web</code> para que los dominios condicionados por features (cloud, publisher, web) estén completos. La verificación de procedencia en <code>docs check</code> compara hashes de cada fuente Rust, así que cualquier cambio en las especificaciones de comandos falla la compilación hasta regenerar el contrato. Las compilaciones normales de documentación nunca ejecutan Cargo.</p><div class="language-sh" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/regenerate-control.ts</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/generate-references.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/scripts/cli-coverage.ts</span></span></code></pre></div><p>Ejecuta la regeneración tras cambiar cualquier parser o especificación de comando, y revisa el diff del fragmento como parte del cambio. Los agentes que consumen <code>help --json</code> deberían tratar la versión 1 del esquema como estable de forma aditiva: pueden aparecer nuevos verbos, dominios o campos sin aviso; las claves existentes mantienen su significado.</p>`,52)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};